import sys
from typing import Any, Dict, List


def extract_connections(payload: Any) -> List[Dict[str, Any]]:
    if isinstance(payload, list):
        return payload
    if not isinstance(payload, dict):
        return []

    for key in ["connections", "data", "items", "result"]:
        value = payload.get(key)
        if isinstance(value, list):
            return value

    return []


def connection_name(connection: Dict[str, Any]) -> str:
    for key in ["toolkit", "toolkit_name", "app", "appName", "name", "provider"]:
        value = connection.get(key)
        if isinstance(value, str) and value:
            return value.lower()
    return ""


def connection_status(connection: Dict[str, Any]) -> str:
    for key in ["status", "connection_status", "connectionStatus"]:
        value = connection.get(key)
        if isinstance(value, str) and value:
            return value.upper()
    return ""


def main() -> int:
    user_id = "zealt-user01"

    try:
        from composio import ComposioToolSet, Action
    except ImportError as exc:
        print("Missing composio package. Install it with 'pip install composio'.", file=sys.stderr)
        return 1

    toolset = ComposioToolSet()

    try:
        response = toolset.execute_action(
            action=Action.COMPOSIO_MANAGE_CONNECTIONS,
            params={
                "user_id": user_id,
                "operation": "LIST",
            },
        )
    except Exception as exc:
        print(f"Failed to list connections: {exc}", file=sys.stderr)
        return 1

    connections = extract_connections(response)
    github_connection = None
    for connection in connections:
        if "github" in connection_name(connection):
            github_connection = connection
            break

    output_path = "/home/user/github_status.json"
    with open(output_path, "w", encoding="utf-8") as handle:
        json.dump(github_connection or {}, handle, indent=2, sort_keys=True)

    if github_connection and connection_status(github_connection) == "CONNECTED":
        print("GitHub is connected")

    return 0


